TRACE_ACTIONS = json.loads(zlib.decompress(base64.b85decode(_PAYLOAD)))


def agent(observation, configuration=None):
    del configuration
    step = min(int(observation.get("step", 0) or 0), len(TRACE_ACTIONS) - 1)
